mapper.sql:
SELECT MIN(a.row_id) AS row_id, a.accrual_id, a.shop_id, MAX(sh.name) AS shop_name, MIN(NULLIF(TRIM(a.product_name), '')) AS product_name, MIN(a.accrual_date) AS first_accrual_date, MAX(a.accrual_date) AS accrual_date, SUM(CASE WHEN a.total_amount_rub > 0 THEN a.total_amount_rub ELSE 0 END) AS positive_amount_rub, SUM(CASE WHEN a.total_amount_rub < 0 THEN a.total_amount_rub ELSE 0 END) AS negative_amount_rub, SUM(a.total_amount_rub) AS total_amount_rub, (SUM(a.total_amount_rub) - SUM(CASE WHEN a.total_amount_rub > 0 THEN a.total_amount_rub ELSE 0 END) * 0.075) AS after_tax_amount_rub, (SUM(a.total_amount_rub) - SUM(CASE WHEN a.total_amount_rub > 0 THEN a.total_amount_rub ELSE 0 END) * 0.075) * 0.075 AS total_amount_cny, COUNT(*) AS record_count FROM ozon_accruals a LEFT JOIN shop sh ON sh.id = a.shop_id
a.accrual_id IS NOT NULL AND TRIM(a.accrual_id) <> ''
AND a.accrual_id = #{q.accrualId}
AND a.shop_id = #{q.scopeShopId}
GROUP BY a.shop_id, a.accrual_id
AND MAX(a.accrual_date) >= #{q.startDate} AND MAX(a.accrual_date) <= #{q.endDate}

SELECT MIN(a.row_id) AS row_id, AS product_key, COALESCE(MAX(NULLIF(TRIM(a.product_name), '')), '未标注商品') AS product_name, MAX(NULLIF(TRIM(a.seller_sku), '')) AS seller_sku, a.accrual_id, COALESCE(MIN(CASE WHEN a.accrual_type = '销售收入' THEN a.order_accepted_or_service_date END), MIN(a.order_accepted_or_service_date), MIN(a.accrual_date)) AS sale_date, MAX(a.accrual_date) AS accrual_date, SUM(a.total_amount_rub) AS sales_amount_rub FROM ozon_accruals a INNER JOIN () s ON s.accrual_id = a.accrual_id AND s.shop_id = a.shop_id WHERE a.total_amount_rub > 0 AND s.total_amount_rub <> 0 AND a.shop_id = #{q.scopeShopId}
AND = #{q.productKey}
GROUP BY product_key, a.accrual_id
